<?php
require_once __DIR__.'/app/lib/Db.php';
$config=require __DIR__.'/app/config.php';
$pdo=Db::pdo();
$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function pct($v){return (int)round(((float)$v)*100);}
function status_label($v){return ucwords(str_replace('_',' ',(string)$v));}
function status_class($v){return $v==='supported'?'ok':(in_array($v,['partially_supported','enterprise_only','plan_dependent','custom_configuration','addon','third_party_integration'],true)?'partial':($v==='not_supported'?'no':'unknown'));}
function initials($name){$parts=preg_split('/\s+/',trim((string)$name));$out='';foreach(array_slice($parts,0,2) as $x){if($x!=='')$out.=mb_strtoupper(mb_substr($x,0,1));}return $out?:'TS';}
function valid_logo($path){if(!$path||!str_starts_with($path,'/media/software/')||str_contains($path,'..'))return null;$full=__DIR__.$path;return is_file($full)?$path:null;}
if(!preg_match('#^/capabilities/([a-z0-9-]+)/?$#',$path,$m)){http_response_code(404);exit('Not found');}
$st=$pdo->prepare("SELECT c.id,c.name,c.slug,c.description,c.is_security_related,mo.name module,cat.name category,cat.slug category_slug FROM capabilities c JOIN modules mo ON mo.id=c.module_id JOIN categories cat ON cat.id=mo.category_id WHERE c.slug=? AND c.is_active=1 AND cat.is_active=1 LIMIT 1");
$st->execute([$m[1]]);$c=$st->fetch();if(!$c){http_response_code(404);exit('Not found');}
$q=$pdo->prepare("SELECT p.id,p.name,p.slug,p.short_description,p.logo_path,v.name vendor,pc.support_status,pc.confidence_score,pc.limitations,pc.implementation_type,pc.last_verified_at,COUNT(DISTINCT pce.evidence_source_id) evidence_count FROM product_capabilities pc JOIN products p ON p.id=pc.product_id LEFT JOIN vendors v ON v.id=p.vendor_id LEFT JOIN product_capability_evidence pce ON pce.product_capability_id=pc.id WHERE pc.capability_id=? AND pc.edition_id IS NULL AND p.status='active' GROUP BY pc.id,p.id ORDER BY CASE pc.support_status WHEN 'supported' THEN 1 WHEN 'partially_supported' THEN 2 WHEN 'enterprise_only' THEN 3 WHEN 'plan_dependent' THEN 4 WHEN 'custom_configuration' THEN 5 WHEN 'addon' THEN 6 WHEN 'third_party_integration' THEN 7 WHEN 'not_yet_verified' THEN 8 WHEN 'unknown' THEN 9 WHEN 'not_supported' THEN 10 ELSE 11 END,pc.confidence_score DESC,p.name");
$q->execute([$c['id']]);$products=$q->fetchAll();
$supported=0;$partial=0;$unknown=0;$notSupported=0;$conf=[];
foreach($products as $x){if($x['support_status']==='supported')$supported++;elseif($x['support_status']==='not_supported')$notSupported++;elseif(in_array($x['support_status'],['unknown','not_yet_verified'],true))$unknown++;else $partial++;if(!in_array($x['support_status'],['unknown','not_yet_verified'],true))$conf[]=(float)$x['confidence_score'];}
$avgConf=$conf?round(array_sum($conf)/count($conf)*100):0;
$desc=$c['description']?:('Compare software support for '.$c['name'].' using evidence-backed TechSelectAI data.');
$canonical=rtrim($config['site_url'],'/').'/capabilities/'.$c['slug'];
$itemLd=[];foreach($products as $i=>$x)$itemLd[]=['@type'=>'ListItem','position'=>$i+1,'url'=>rtrim($config['site_url'],'/').'/software/'.$x['slug'],'name'=>$x['name']];
$ld=['@context'=>'https://schema.org','@type'=>'ItemList','name'=>$c['name'].' software support','itemListElement'=>$itemLd];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($c['name'])?> Software Comparison | TechSelectAI</title><meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e($canonical)?>"><meta property="og:type" content="website"><meta property="og:title" content="<?=e($c['name'])?> Software Comparison | TechSelectAI"><meta property="og:description" content="<?=e($desc)?>"><meta property="og:url" content="<?=e($canonical)?>"><script type="application/ld+json"><?=json_encode($ld,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)?></script><style>:root{--navy:#123b67;--ink:#172033;--muted:#64748b;--line:#e2e8f0;--soft:#f7fafc;--green:#137a55;--greenbg:#e9f8f1;--amber:#95610a;--amberbg:#fff7df;--red:#b42318;--redbg:#fff0ee}*{box-sizing:border-box}body{margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:var(--ink);background:#fff}a{color:#145ea8}header{display:flex;justify-content:space-between;align-items:center;padding:17px max(24px,5vw);border-bottom:1px solid var(--line)}header>a{font-size:20px;font-weight:800;color:var(--navy);text-decoration:none}nav a{margin-left:20px;text-decoration:none;font-weight:650;color:#334155}.wrap{max-width:1160px;margin:auto;padding:0 24px}.crumbs{font-size:13px;color:var(--muted);padding-top:25px}.hero{padding:38px 0 20px}.eyebrow{font-size:12px;letter-spacing:.09em;text-transform:uppercase;color:#52708b;font-weight:800}.hero h1{font-size:clamp(36px,5vw,58px);line-height:1.03;margin:8px 0 13px}.lead{font-size:19px;line-height:1.65;color:#536174;max-width:900px}.stats{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.pill{padding:8px 11px;border-radius:999px;background:#f1f6f9;color:#31516e;font-size:13px;font-weight:700}.section{padding-top:34px}.section h2{font-size:28px;margin:0 0 8px}.intro{color:var(--muted);margin:0 0 18px;line-height:1.6}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:15px}.comparison{width:100%;border-collapse:collapse;min-width:820px}.comparison th,.comparison td{text-align:left;padding:15px;border-bottom:1px solid var(--line);vertical-align:top}.comparison th{background:var(--soft);font-size:12px;color:#526071}.product{display:flex;gap:12px;align-items:center}.mark{width:46px;height:46px;border-radius:11px;border:1px solid #dbe5ec;background:#f4f8fa;display:grid;place-items:center;overflow:hidden;flex:0 0 auto;color:var(--navy);font-weight:850}.mark img{width:100%;height:100%;object-fit:contain;padding:5px}.badge{display:inline-block;border-radius:999px;padding:5px 9px;font-size:11px;font-weight:800}.badge.ok{color:var(--green);background:var(--greenbg)}.badge.partial{color:var(--amber);background:var(--amberbg)}.badge.no{color:var(--red);background:var(--redbg)}.badge.unknown{color:#596579;background:#eef2f7}.muted{color:var(--muted);font-size:13px;line-height:1.45}.card-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:14px}.card{border:1px solid var(--line);border-radius:14px;padding:17px;background:#fff}.card h3{margin:0 0 8px;font-size:17px}.cta{margin:42px 0 0;padding:26px;border-radius:17px;background:linear-gradient(135deg,#f0f8fb,#f5f8fc);border:1px solid #d5e5ed}.btn{display:inline-block;margin-top:8px;padding:11px 16px;border-radius:10px;background:var(--navy);color:#fff;text-decoration:none;font-weight:750}footer{margin:56px 0 30px;color:var(--muted);font-size:13px}@media(max-width:650px){nav{display:none}}</style></head><body><header><a href="/">TechSelectAI</a><nav><a href="/software">Software</a><a href="/categories/<?=e($c['category_slug'])?>"><?=e($c['category'])?></a><a href="/methodology">Methodology</a><a href="/">Get Advice</a></nav></header><main class="wrap"><div class="crumbs"><a href="/">Home</a> / <a href="/categories/<?=e($c['category_slug'])?>"><?=e($c['category'])?></a> / <?=e($c['name'])?></div><section class="hero"><div class="eyebrow"><?=e($c['category'])?> · <?=e($c['module'])?></div><h1><?=e($c['name'])?></h1><p class="lead"><?=e($desc)?></p><div class="stats"><span class="pill"><?=count($products)?> products evaluated</span><span class="pill"><?=$supported?> supported</span><span class="pill"><?=$partial?> partial / conditional</span><span class="pill"><?=$unknown?> not yet verified</span><span class="pill"><?=$notSupported?> not supported</span><span class="pill">Avg evidence confidence <?=$avgConf?>%</span><?php if($c['is_security_related']):?><span class="pill">Security-related capability</span><?php endif;?></div></section><section class="section"><h2>Product support comparison</h2><p class="intro">Recorded product facts are shown separately from buyer-specific recommendation scores. “Not yet verified” means evidence is incomplete; it does not mean the product lacks the capability.</p><?php if(!$products):?><div class="card">No active products currently have a recorded fact for this capability.</div><?php else:?><div class="table-wrap"><table class="comparison"><thead><tr><th>Product</th><th>Status</th><th>Confidence</th><th>Implementation</th><th>Evidence</th><th>Limitations / notes</th><th>Last verified</th></tr></thead><tbody><?php foreach($products as $x):$logo=valid_logo($x['logo_path']);?><tr><td><div class="product"><div class="mark"><?php if($logo):?><img src="<?=e($logo)?>" alt="<?=e($x['name'])?> logo"><?php else:?><?=e(initials($x['name']))?><?php endif;?></div><div><strong><a href="/software/<?=e($x['slug'])?>"><?=e($x['name'])?></a></strong><div class="muted"><?=e($x['vendor']?:'Vendor not recorded')?></div></div></div></td><td><span class="badge <?=status_class($x['support_status'])?>"><?=e(status_label($x['support_status']))?></span></td><td><strong><?=pct($x['confidence_score'])?>%</strong></td><td><?=e($x['implementation_type']?:'Not recorded')?></td><td><?=intval($x['evidence_count'])?> source<?=intval($x['evidence_count'])===1?'':'s'?></td><td class="muted"><?=e($x['limitations']?:'No limitation recorded.')?></td><td class="muted"><?=e($x['last_verified_at']?date('M j, Y',strtotime($x['last_verified_at'])):'Not recorded')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><section class="section"><h2>How to use this comparison</h2><div class="card-grid"><div class="card"><h3>Support status</h3><p class="muted">Supported, conditional, unknown and not-supported states are kept distinct so missing evidence is not treated as a negative fact.</p></div><div class="card"><h3>Confidence</h3><p class="muted">Confidence reflects the strength of the recorded evidence for this capability, not overall product quality.</p></div><div class="card"><h3>Fit for your company</h3><p class="muted">A product can strongly support this capability and still be a poor overall fit due to deployment, integrations, security, region, budget or other must-haves.</p></div></div></section><section class="cta"><div class="eyebrow">Independent software advice</div><h2>Need <?=e($c['name'])?> in your next system?</h2><p>TechSelectAI can evaluate this capability together with your other must-haves, integrations, deployment constraints, security requirements, region and budget.</p><a class="btn" href="/?considering=<?=rawurlencode($c['name'])?>">Evaluate software for my company</a></section><footer>TechSelectAI uses evidence-backed product data. Unknown means not yet verified; it does not mean unsupported. Vendor names and trademarks belong to their respective owners.</footer></main></body></html>